/// <summary>
/// PE Pricing POC Task 96965: Generate invoices for sales orders, validate account allocation.
/// Create discount claims in the std table and bypass the relation validation on discount id as this will come from PE
/// </summary>
[ExtensionOf(classStr(GUPDiscountClaimProcessDialog))]
final class METGUPDiscountClaimProcessDialogCls_Extension
{
}

Method.Source:
    public void initQueryRun()
    {
        next initQueryRun();

        // change the join to outer join as GUPDiscountClaim.DiscountId may not exist in RetailPeriodicDiscount anymore
        Query q = queryRun.query();
        QueryBuildDataSource qbds = q.dataSourceTable(tableNum(RetailPeriodicDiscount));
        qbds.joinMode(JoinMode::OuterJoin);
    }
